import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { NumberField } from "@base-ui/react/number-field";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { IconMinus, IconPlus, IconTrash } from "@tabler/icons-react";
import { cn } from "@/lib/utils";

export type NumberInputSize = "sm" | "md" | "lg";
export type NumberInputVariant = "default" | "cart";
export type NumberInputLayout = "split" | "trailing";

type ChangeReason = NumberField.Root.ChangeEventDetails["reason"];

export interface NumberInputProps {
  /** Controlled value. `null` means the field is empty. */
  value?: number | null;
  /** Uncontrolled starting value. */
  defaultValue?: number;
  onValueChange?: (value: number | null, reason: ChangeReason) => void;
  /** Fires on blur after typing, and on pointer release after a press or hold. */
  onValueCommitted?: (value: number | null) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Step while Shift is held. */
  largeStep?: number;
  /** Step while Alt is held. */
  smallStep?: number;
  /** Intl.NumberFormat options: currency, percent, units, fraction digits. */
  format?: Intl.NumberFormatOptions;
  locale?: Intl.LocalesArgument;
  /** `cart` swaps minus for a remove button once the value sits at `min`. */
  variant?: NumberInputVariant;
  /** Called when the remove button is pressed in the cart variant. */
  onRemove?: () => void;
  /** `split` puts minus and plus either side, `trailing` groups both on the right. */
  layout?: NumberInputLayout;
  size?: NumberInputSize;
  /** Rolls each digit up or down as the value changes. */
  rolling?: boolean;
  /** Steps with the mouse wheel while the field is focused and hovered. */
  wheelStep?: boolean;
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  name?: string;
  id?: string;
  fullWidth?: boolean;
  incrementLabel?: string;
  decrementLabel?: string;
  removeLabel?: string;
  "aria-label"?: string;
  className?: string;
  inputClassName?: string;
}

// Motion tiers shared by every primitive. No bounce anywhere.
const SPRING = {
  fast: { type: "spring", duration: 0.08, bounce: 0 },
  moderate: { type: "spring", duration: 0.16, bounce: 0 },
  slow: { type: "spring", duration: 0.24, bounce: 0 },
} as const;

const FIELD_HEIGHT: Record<NumberInputSize, string> = {
  sm: "h-[var(--primitive-control-height-sm)]",
  md: "h-[var(--primitive-control-height-md)]",
  lg: "h-[var(--primitive-control-height-lg)]",
};

// Buttons sit 3px inside the field so the field rim frames them.
const BUTTON_SIZE: Record<NumberInputSize, string> = {
  sm: "size-[calc(var(--primitive-control-height-sm)-6px)]",
  md: "size-[calc(var(--primitive-control-height-md)-6px)]",
  lg: "size-[calc(var(--primitive-control-height-lg)-6px)]",
};

const ICON_SIZE: Record<NumberInputSize, number> = { sm: 13, md: 14, lg: 16 };

const TEXT_SIZE: Record<NumberInputSize, string> = {
  sm: "text-xs",
  md: "text-sm",
  lg: "text-[15px]",
};

const fieldClass = cn(
  "group/number relative isolate inline-flex items-center gap-[3px] p-[3px]",
  // Recess and depth come from data-surface="well".
  "rounded-[var(--primitive-radius-control)]",
  "transition-[box-shadow] duration-[var(--primitive-motion-fast)] ease-[var(--primitive-ease)]",
  "motion-reduce:transition-none",
);

const fieldFocus = cn(
  "has-[input:focus-visible]:ring-2 has-[input:focus-visible]:ring-[var(--primitive-ring)]",
  "has-[input:focus-visible]:ring-offset-2 has-[input:focus-visible]:ring-offset-[var(--background)]",
);

const fieldError = cn(
  "[--surface-rim:var(--primitive-destructive-border)]",
  "has-[input:focus-visible]:ring-2 has-[input:focus-visible]:ring-[color-mix(in_srgb,var(--primitive-destructive)_45%,transparent)]",
  "has-[input:focus-visible]:ring-offset-2 has-[input:focus-visible]:ring-offset-[var(--background)]",
);

const buttonClass = cn(
  "relative grid shrink-0 place-items-center overflow-hidden select-none touch-manipulation",
  // Carved: face, rim, catchlight and press recess come from data-surface="control".
  "rounded-[calc(var(--primitive-radius-control)-3px)]",
  "text-[var(--muted-foreground)]",
  "transition-[color,background-color,box-shadow,opacity,translate] duration-[var(--primitive-motion-moderate)] ease-[var(--primitive-ease)]",
  "hover:text-[var(--foreground)]",
  "active:translate-y-px active:[transition-duration:var(--primitive-motion-fast)]",
  "motion-reduce:transition-none motion-reduce:active:translate-y-0",
  "outline-none focus-visible:ring-2 focus-visible:ring-[var(--primitive-ring)] focus-visible:ring-offset-1 focus-visible:ring-offset-[var(--background)]",
  "disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:text-[var(--muted-foreground)]",
);

const removeClass = cn(
  buttonClass,
  "hover:text-[var(--primitive-destructive)] focus-visible:text-[var(--primitive-destructive)]",
);

// Cart icon swap: CSS transitions, so a fast toggle retargets mid-way.
const swapIconClass = cn(
  "grid place-items-center",
  "transition-[opacity,scale,rotate] duration-[var(--primitive-motion-moderate)] ease-[var(--primitive-ease)]",
  "motion-reduce:transition-none",
);
const swapIconIn = "opacity-100 scale-100 rotate-0";
const swapIconOut = "opacity-0 scale-[0.6]";
const swapIconOutRotated = "opacity-0 scale-[0.6] -rotate-[24deg]";

function formatValue(
  value: number | null,
  locale: Intl.LocalesArgument | undefined,
  format: Intl.NumberFormatOptions | undefined,
) {
  if (value == null || Number.isNaN(value)) return "";
  try {
    return new Intl.NumberFormat(locale, format).format(value);
  } catch {
    return String(value);
  }
}

function isDigit(char: string) {
  return char >= "0" && char <= "9";
}

/* ─── Rolling digits ───────────────────────────────────────── */

function RollingDigit({
  char,
  direction,
  reduceMotion,
}: {
  char: string;
  direction: number;
  reduceMotion: boolean;
}) {
  if (reduceMotion) return <span className="inline-block">{char}</span>;
  return (
    <span className="relative inline-flex h-[1lh] overflow-hidden [mask-image:linear-gradient(to_bottom,transparent,#000_12%,#000_88%,transparent)]">
      <AnimatePresence initial={false} mode="popLayout" custom={direction}>
        <motion.span
          key={char}
          custom={direction}
          variants={{
            enter: (dir: number) => ({
              transform: dir >= 0 ? "translateY(100%)" : "translateY(-100%)",
              opacity: 0,
            }),
            center: { transform: "translateY(0%)", opacity: 1 },
            exit: (dir: number) => ({
              transform: dir >= 0 ? "translateY(-100%)" : "translateY(100%)",
              opacity: 0,
            }),
          }}
          initial="enter"
          animate="center"
          exit="exit"
          transition={SPRING.moderate}
          className="inline-block"
        >
          {char}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

function RollingValue({
  text,
  direction,
  reduceMotion,
}: {
  text: string;
  direction: number;
  reduceMotion: boolean;
}) {
  const chars = Array.from(text);
  // Slots are keyed from the right, so 9 → 10 rolls the ones digit and adds a
  // tens slot on the left instead of shifting every digit one place.
  return (
    <>
      {chars.map((char, index) => {
        const slot = chars.length - index;
        return isDigit(char) ? (
          <RollingDigit
            key={`d${slot}`}
            char={char}
            direction={direction}
            reduceMotion={reduceMotion}
          />
        ) : (
          <span key={`s${slot}`} className="inline-block whitespace-pre">
            {char}
          </span>
        );
      })}
    </>
  );
}

/* ─── <NumberInput> ────────────────────────────────────────── */

export const NumberInput = React.forwardRef<HTMLInputElement, NumberInputProps>(
  (
    {
      value: valueProp,
      defaultValue,
      onValueChange,
      onValueCommitted,
      min: minProp,
      max,
      step = 1,
      largeStep,
      smallStep,
      format,
      locale,
      variant = "default",
      onRemove,
      layout = "split",
      size = "md",
      rolling = true,
      wheelStep = true,
      label,
      hint,
      error,
      placeholder,
      disabled,
      readOnly,
      required,
      name,
      id,
      fullWidth = false,
      incrementLabel = "Increase",
      decrementLabel = "Decrease",
      removeLabel = "Remove",
      "aria-label": ariaLabel,
      className,
      inputClassName,
    },
    ref,
  ) => {
    const reduceMotion = useReducedMotion() ?? false;
    const reactId = React.useId();
    const inputId = id ?? `wensity-number-${reactId}`;
    const hintId = hint ? `${inputId}-hint` : undefined;
    const errorId = error ? `${inputId}-error` : undefined;
    const describedBy = [errorId, hintId].filter(Boolean).join(" ") || undefined;

    // A cart line never goes below one unless told otherwise.
    const min = minProp ?? (variant === "cart" ? 1 : undefined);

    const isControlled = valueProp !== undefined;
    const [inner, setInner] = React.useState<number | null>(defaultValue ?? null);
    const current = isControlled ? (valueProp ?? null) : inner;

    // While the user types, show the real input text. Stepping hands the
    // display back to the rolling digits.
    const [editing, setEditing] = React.useState(false);
    // Direction is set during render, before the new digit mounts, so the
    // first press after a change of direction already rolls the right way.
    const [prevValue, setPrevValue] = React.useState<number | null>(current);
    const [direction, setDirection] = React.useState(1);
    if (current !== prevValue) {
      if (prevValue != null && current != null) {
        setDirection(current > prevValue ? 1 : -1);
      }
      setPrevValue(current);
    }

    const handleChange = React.useCallback(
      (next: number | null, details: NumberField.Root.ChangeEventDetails) => {
        const reason = details.reason;
        setEditing(
          reason === "input-change" || reason === "input-clear" || reason === "input-paste",
        );
        if (!isControlled) setInner(next);
        onValueChange?.(next, reason);
      },
      [isControlled, onValueChange],
    );

    const formatted = formatValue(current, locale, format);
    const showRoll = rolling && !editing && formatted !== "";

    // Size the field to the widest value it can hold, so it never jumps.
    const widest = Math.max(
      3,
      // Without a max there is no widest value, so leave room to grow.
      formatted.length + (max == null ? 2 : 0),
      max != null && Number.isFinite(max) ? formatValue(max, locale, format).length : 0,
      min != null && Number.isFinite(min) ? formatValue(min, locale, format).length : 0,
      placeholder?.length ?? 0,
    );

    const atMin = current != null && min != null && current <= min;
    const showRemove = variant === "cart" && atMin && !disabled && !readOnly;
    const iconSize = ICON_SIZE[size];

    const minusButton = (
      <NumberField.Decrement
        data-surface="control"
        data-slot="number-input-decrement"
        aria-label={decrementLabel}
        aria-hidden={showRemove ? true : undefined}
        className={cn(
          buttonClass,
          BUTTON_SIZE[size],
          // Under the remove button its face stays solid, so the swap only
          // ever changes the icon, never dims the button.
          showRemove && "opacity-100!",
        )}
      >
        <span className={cn(swapIconClass, showRemove ? swapIconOut : swapIconIn)}>
          <IconMinus size={iconSize} stroke={2} aria-hidden="true" />
        </span>
      </NumberField.Decrement>
    );

    // Cart: both buttons stay mounted in one slot and the remove button fades
    // in on top at the minimum. A held minus stops at the minimum and never
    // deletes, because the release lands on a different element.
    const decrement =
      variant === "cart" ? (
        <span className="grid shrink-0 [&>*]:[grid-area:1/1]">
          {minusButton}
          <button
            type="button"
            data-surface="control"
            data-slot="number-input-remove"
            aria-label={removeLabel}
            aria-hidden={showRemove ? undefined : true}
            tabIndex={showRemove ? 0 : -1}
            onClick={showRemove ? onRemove : undefined}
            className={cn(
              removeClass,
              BUTTON_SIZE[size],
              "transition-[color,background-color,box-shadow,opacity,translate]",
              showRemove ? "opacity-100" : "pointer-events-none opacity-0",
            )}
          >
            <span className={cn(swapIconClass, showRemove ? swapIconIn : swapIconOutRotated)}>
              <IconTrash size={iconSize} stroke={1.75} aria-hidden="true" />
            </span>
          </button>
        </span>
      ) : (
        minusButton
      );

    const increment = (
      <NumberField.Increment
        data-surface="control"
        data-slot="number-input-increment"
        aria-label={incrementLabel}
        className={cn(buttonClass, BUTTON_SIZE[size])}
      >
        <IconPlus size={iconSize} stroke={2} aria-hidden="true" />
      </NumberField.Increment>
    );

    const trailing = layout === "trailing";

    return (
      <div
        data-wensity-primitive=""
        className={cn("flex flex-col gap-2", fullWidth ? "w-full" : "w-fit", className)}
      >
        {label ? (
          <label
            htmlFor={inputId}
            className="text-[13px] font-medium leading-none tracking-[-0.01em] text-[var(--foreground)]"
          >
            {label}
          </label>
        ) : null}

        <NumberField.Root
          id={inputId}
          value={current}
          onValueChange={handleChange}
          onValueCommitted={(next) => {
            setEditing(false);
            onValueCommitted?.(next);
          }}
          min={min}
          max={max}
          step={step}
          largeStep={largeStep}
          smallStep={smallStep}
          format={format}
          locale={locale}
          allowWheelScrub={wheelStep}
          disabled={disabled}
          readOnly={readOnly}
          required={required}
          name={name}
          className={fullWidth ? "w-full" : "w-fit"}
        >
          <NumberField.Group
            // A recessed track with the carved buttons raised inside it, like a
            // segmented control: one lit edge per layer, never two.
            data-surface="well"
            data-slot="number-input"
            data-variant={variant}
            className={cn(
              fieldClass,
              FIELD_HEIGHT[size],
              fullWidth && "flex w-full",
              !disabled && !readOnly && (error ? fieldError : fieldFocus),
              disabled && "cursor-not-allowed opacity-45",
              readOnly && "[--surface-face:var(--muted)]",
            )}
          >
            {trailing ? null : decrement}

            <div
              className={cn(
                "relative flex h-full min-w-0 items-center",
                fullWidth && "flex-1",
                TEXT_SIZE[size],
              )}
            >
              <NumberField.Input
                ref={ref}
                placeholder={placeholder}
                aria-label={label ? undefined : ariaLabel}
                aria-invalid={error ? true : undefined}
                aria-describedby={describedBy}
                style={fullWidth ? undefined : { width: `calc(${widest}ch + 1rem)` }}
                className={cn(
                  "h-full min-w-0 border-0 bg-transparent px-2 font-medium tabular-nums outline-none",
                  trailing ? "text-left pl-2.5" : "text-center",
                  fullWidth && "w-full",
                  "text-[var(--foreground)] caret-[var(--foreground)]",
                  // 16px on touch screens: iOS zooms into any field set smaller.
                  "pointer-coarse:text-base",
                  "placeholder:font-normal placeholder:text-[var(--primitive-text-placeholder)]",
                  "selection:bg-[color-mix(in_srgb,var(--foreground)_18%,transparent)]",
                  "disabled:cursor-not-allowed read-only:text-[var(--muted-foreground)]",
                  showRoll && "text-transparent",
                  inputClassName,
                )}
              />
              {showRoll ? (
                <span
                  aria-hidden="true"
                  className={cn(
                    "pointer-events-none absolute inset-0 flex items-center px-2 font-medium tabular-nums whitespace-nowrap",
                    trailing ? "justify-start pl-2.5" : "justify-center",
                    "pointer-coarse:text-base",
                    readOnly ? "text-[var(--muted-foreground)]" : "text-[var(--foreground)]",
                  )}
                >
                  <RollingValue
                    text={formatted}
                    direction={direction}
                    reduceMotion={reduceMotion}
                  />
                </span>
              ) : null}
            </div>

            {trailing ? (
              <>
                {decrement}
                {increment}
              </>
            ) : (
              increment
            )}
          </NumberField.Group>
        </NumberField.Root>

        {error ? (
          <p id={errorId} className="text-[12px] leading-[1.45] text-[var(--primitive-destructive)]">
            {error}
          </p>
        ) : hint ? (
          <p id={hintId} className="text-[12px] leading-[1.45] text-[var(--primitive-text-secondary)]">
            {hint}
          </p>
        ) : null}
      </div>
    );
  },
);

NumberInput.displayName = "NumberInput";
